// Better Auth signs email-verification tokens (HS256) and session cookies, and
// encrypts stored OAuth tokens, with this secret. It only *warns* when an
// explicitly configured secret is short or low-entropy. A guessable secret lets
// anyone forge a change-email token for the public GET /api/auth/verify-email
// endpoint and take over an account. So in production we refuse to start
// unless every configured secret is at least 32 bytes of random material,
// generated by `npx auth secret` (hex) or `openssl rand -base64 32`.
//
// This can reject weak and hand-typed secrets, but it can't prove randomness:
// a long phrase that happens to be valid base64 still passes. Always generate
// the secret.

const MIN_BYTES = 32;
// Random bytes almost never repeat this much. 32 random bytes average ~30 distinct values.
const MIN_DISTINCT_BYTES = 20;
// Better Auth's built-in development fallback (better-auth/dist/utils/constants).
const DEFAULT_SECRET = "better-auth-secret-12345678901234567890";

type Env = Record<string, string | undefined>;
type ConfiguredSecret = { name: string; value: string };

/** The secrets Better Auth will use, in the order it resolves them. */
function configuredSecrets(env: Env): ConfiguredSecret[] {
  // BETTER_AUTH_SECRETS ("<version>:<secret>,…") takes precedence when set.
  if (env.BETTER_AUTH_SECRETS) {
    return env.BETTER_AUTH_SECRETS.split(",")
      .map((entry) => entry.trim())
      .filter(Boolean)
      .map((entry) => {
        const colon = entry.indexOf(":");
        return {
          name: `BETTER_AUTH_SECRETS (version ${entry.slice(0, colon)})`,
          value: entry.slice(colon + 1).trim(),
        };
      });
  }
  if (env.BETTER_AUTH_SECRET) return [{ name: "BETTER_AUTH_SECRET", value: env.BETTER_AUTH_SECRET }];
  if (env.AUTH_SECRET) return [{ name: "AUTH_SECRET", value: env.AUTH_SECRET }];
  return [];
}

/** Hex or base64/base64url text, decoded; null for anything else. */
function decode(secret: string) {
  if (/^[0-9a-f]+$/i.test(secret) && secret.length % 2 === 0) {
    return Buffer.from(secret, "hex");
  }
  if (/^[A-Za-z0-9+/]+={0,2}$/.test(secret) || /^[A-Za-z0-9_-]+$/.test(secret)) {
    return Buffer.from(secret, "base64");
  }
  return null;
}

/** Why `secret` is unacceptable, or null if it looks like generated random material. */
function weakness(secret: string): string | null {
  if (secret === DEFAULT_SECRET) return "is Better Auth's public default secret";
  const bytes = decode(secret);
  if (!bytes) return "is not hex or base64 (generate it, don't type it)";
  if (bytes.length < MIN_BYTES) {
    return `decodes to ${bytes.length} bytes; at least ${MIN_BYTES} are required`;
  }
  if (new Set(bytes).size < MIN_DISTINCT_BYTES) return "is too repetitive to be random";
  return null;
}

/**
 * Throws in production when the auth secret is missing or weak; elsewhere only
 * warns, so `auth:generate` and local development work without one.
 * Messages name the variable but never include the secret itself.
 */
export function assertStrongAuthSecret(env: Env = process.env) {
  const secrets = configuredSecrets(env);
  const problems = secrets.flatMap(({ name, value }) => {
    const reason = weakness(value);
    return reason ? [`${name} ${reason}`] : [];
  });
  const fix = "Generate one with `npx auth secret` or `openssl rand -base64 32`.";

  if (env.NODE_ENV !== "production") {
    if (problems.length > 0) {
      console.warn(`[auth] Weak auth secret: ${problems.join("; ")}. ${fix}`);
    }
    return;
  }
  if (secrets.length === 0) {
    throw new Error(`[auth] BETTER_AUTH_SECRET is not set. ${fix}`);
  }
  if (problems.length > 0) {
    throw new Error(`[auth] Refusing to start with a weak auth secret: ${problems.join("; ")}. ${fix}`);
  }
}
